      setEditing(null);
      setName('');
      setGrade('A');
      setGradeFrom('');
      setTerms('');
      setTermsFrom('');
      setContact('');
      setTags('');
    },
    onSuccess: async () => {
      setEditing(null);
      setName('');
      setGrade('A');
      setGradeFrom('');
      setTerms('');
      setTermsFrom('');
      setContact('');
      setTags('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
